async function request<T=unknown>(url:string,method='GET',body?:unknown):Promise<T>{const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},...(body!==undefined&&method!=='GET'?{body:JSON.stringify(body)}:{})});const data=await r.json() as {error?:string};if(!r.ok)throw new Error(data.error||'操作未完成');return data as T;}
function Brand({platform,small=false}:{platform:Platform;small?:boolean}){return <span className={`brand ${platform} ${small?'small':''}`} title={platformNames[platform]}>{({facebook:'f',instagram:'◎',threads:'@',line:'LINE'})[platform]}</span>;}
function Badge({status,children}:{status:string;children?:ReactNode}){return <span className={`badge ${status}`}><i/>{children||statusNames[status]||status}</span>;}
function Empty({title,text,children}:{title:string;text:string;children?:ReactNode}){return <div className="empty"><Leaf size={32}/><h3>{title}</h3><p>{text}</p>{children}</div>;}
function Modal({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}){const ref=useRef<HTMLDialogElement>(null),titleId=useId();useEffect(()=>{const el=ref.current;el?.showModal();return()=>el?.close();},[]);return <dialog className={`modal ${wide?'wide':''}`} ref={ref} aria-labelledby={titleId} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><header><h2 id={titleId}>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="關閉視窗"><X size={21}/></button></header>{children}</dialog>;}
