  const [editor,setEditor]=useState<Post|null>(null),[selectedPlatform,setSelectedPlatform]=useState<Platform>('facebook'),[reviewed,setReviewed]=useState(false),[sourceModal,setSourceModal]=useState(false),[sourceEdit,setSourceEdit]=useState<Source|null>(null),[sourceMode,setSourceMode]=useState<'manual'|'url'|'subscription'>('manual'),[sourceDetail,setSourceDetail]=useState<Article|null>(null),[mediaPick,setMediaPick]=useState(false),[cardModal,setCardModal]=useState(false),[query,setQuery]=useState(''),[queueTab,setQueueTab]=useState<'queue'|'backup'|'history'>('queue'),[settingsTab,setSettingsTab]=useState<'unit'|'automation'|'ai'|'mail'|'security'>('unit'),[confirmAction,setConfirmAction]=useState<{title:string;text:string;confirmText?:string;run:()=>Promise<void>}|null>(null);
  const [previewIndex,setPreviewIndex]=useState(0);
  const [toastTone,setToastTone]=useState<'success'|'error'>('success');
